<div class="form-grid"><div class="field"><label>Student Code</label><input class="input" name="student_code" value="<?php echo e(old('student_code', $student->student_code ?? '')); ?>" required></div><div class="field"><label>Department</label><select class="select" name="department_id" required><option value="">Select department</option><?php $__currentLoopData = $departments; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $dept): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><option value="<?php echo e($dept->id); ?>" <?php if(old('department_id', $student->department_id ?? '') == $dept->id): echo 'selected'; endif; ?>><?php echo e($dept->name); ?> (<?php echo e($dept->code); ?>)</option><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></select></div><div class="field"><label>First Name</label><input class="input" name="first_name" value="<?php echo e(old('first_name', $student->first_name ?? '')); ?>" required></div><div class="field"><label>Last Name</label><input class="input" name="last_name" value="<?php echo e(old('last_name', $student->last_name ?? '')); ?>" required></div><div class="field"><label>Gender</label><select class="select" name="gender" required><option value="">Select gender</option><?php $__currentLoopData = ['Male','Female','Other']; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $gender): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><option value="<?php echo e($gender); ?>" <?php if(old('gender', $student->gender ?? '') === $gender): echo 'selected'; endif; ?>><?php echo e($gender); ?></option><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></select></div><div class="field"><label>Date of Birth</label><input class="input" type="date" name="dob" value="<?php echo e(old('dob', isset($student) && $student->dob ? $student->dob->format('Y-m-d') : '')); ?>"></div><div class="field"><label>Phone</label><input class="input" name="phone" value="<?php echo e(old('phone', $student->phone ?? '')); ?>"></div></div><div class="form-actions"><a class="btn btn-light" href="<?php echo e(route('students.index')); ?>">Cancel</a><button class="btn btn-primary" type="submit"><?php echo e($buttonText); ?></button></div><?php /**PATH C:\laragon\www\attendance_management_laravel13\resources\views/students/_form.blade.php ENDPATH**/ ?>